import{_ as a,c as t,a2 as i,o as p}from"./chunks/framework.C3Q6VB1z.js";const h=JSON.parse('{"title":"《围城》观后感","description":"","frontmatter":{},"headers":[],"relativePath":"life/essay/20250227-thingk.md","filePath":"life/essay/20250227-thingk.md"}'),l={name:"life/essay/20250227-thingk.md"};function s(o,e,r,n,c,d){return p(),t("div",null,e[0]||(e[0]=[i('<h1 id="《围城》观后感" tabindex="-1">《围城》观后感 <a class="header-anchor" href="#《围城》观后感" aria-label="Permalink to &quot;《围城》观后感&quot;">​</a></h1><p>好早就听说过《围城》这部小说，但一直没有看过。直到过年的时候，看到李笑来老师的一本书上引用了这部小说里的话，我才决定要看看这部小说。好书里推荐的书应该都不差，所以立马去拼多多下单了一本。</p><p>其实看了第一章我就后悔了，感觉一般般子。过了两天又捡起来重头看，发现越看越有意思，越看越上瘾。直呼说话真是一门艺术！！！</p><p>怎么说这本书呢？故事普普通通的，简单的介绍了一个混混的大半辈子。并没有什么跌宕起伏的情节，也没有什么惊天动地的故事。有的只是日常生活中的琐事，以及一些看似平淡无奇的对话。但是，正是这些琐事中的对话，才是这本书的精华所在。通过各种对话，来展现人物的性格，以及人物之间的关系。比如开头的一个场景，小孩子在船上玩耍，他妈妈和苏小姐的对话，把苏小姐一顿猛夸，说的人直接飘飘然了。原本苏小姐还挺生气，听完之后直接就笑了。还给了小孩子糖吃。简简单单的几句话，我就知道，这本书值得我继续看下去。我现在就是缺少这种“知识”，我需要学习这种说话的艺术。</p><p>还有方鸿渐在对待苏小姐和唐小姐的方式方法上，简直了。苏小姐和唐小姐都是那种比较强势的人，但是方鸿渐却能通过各种方式方法，让她们两个人都对他有好感。这种能力，真的是我需要学习的。能够做到对不同的人说不同的话，同时又不会让人讨厌，恰到好处，又难以让人拒绝。真的牛批！！！</p><p>特别是方鸿渐在学校里当副教授那段，机制化解挑拨离间，胆大心细，对于为人处事方面拿捏的死死的。确实，在社会上混，有时候真的需要这种能力。</p><p>不过，最厉害的还是赵辛楣，也是一个很厉害的角色，各方面都碾压方鸿渐。他的为人处事也是很值得学习的。</p><p>但是啊但是，看完这本书后，对于方鸿渐我还是很生气的。他这个人，只会耍嘴炮，只会窝里横，只会逃避。对于唐小姐，喜欢又不敢面对；和别人结婚了之后又一直对唐小姐念念不忘，说什么没遇到真爱。有一说一，对他老婆确实不咋地，还是封建思想有点严重。</p><p>有好有坏吧。对于这本书，我还是很喜欢的。学习他们之间的对话，学习他们之间的为人处事。什么儿女情长，只会耽误我搞钱！！！</p><p>-----------------------------------重点感悟-----------------------------------</p><ol><li>说话有时候得揣着明白装糊涂，不然容易得罪人。</li><li>场面话很重要，但是不能多说，说多了就假了。</li><li>要懂得夸人，夸到点子上，夸到别人心里去。</li><li>做人留一线，日后好相见。</li></ol>',11)]))}const m=a(l,[["render",s]]);export{h as __pageData,m as default};
